# area: overloads
# hypothesis: Literal-typed overloads pick the matching return type for literal arguments and for a union argument via union math, while a second overload with the same parameter type but an incompatible return type is flagged as overlapping by mypy and ty.
from typing import Literal, assert_type, overload, reveal_type


@overload
def mode(flag: Literal['r']) -> int: ...
@overload
def mode(flag: Literal['w']) -> str: ...
def mode(flag: str) -> int | str:
    return 0 if flag == 'r' else 'w'


def run(flag: Literal['r', 'w']) -> int | str:
    return mode(flag)


@overload
def pick[T](xs: list[T]) -> T: ...
@overload
def pick(xs: str) -> str: ...
def pick[T](xs: list[T] | str) -> T | str:
    return xs[0]


@overload
def dup(x: int) -> int: ...
@overload
def dup(x: int) -> str: ...  # expect-error
def dup(x: int) -> int | str:
    return x


r = mode('r')
assert_type(r, int)
w = mode('w')
assert_type(w, str)
reveal_type(run('w'))
assert run('r') == 0
assert run('w') == 'w'
i = pick([1, 2])
assert_type(i, int)
assert pick('ab') == 'a'
assert dup(1) == 1
